import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.DXGyWiRo.js";const g=JSON.parse('{"title":"Call API","description":"","frontmatter":{},"headers":[],"relativePath":"guide/call.md","filePath":"guide/call.md","lastUpdated":1789862141000}'),n={name:"guide/call.md"};function r(i,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="call-api" tabindex="-1">Call API <a class="header-anchor" href="#call-api" aria-label="Permalink to &quot;Call API&quot;">​</a></h1><p>EasyYapi supports sending API requests directly from IDEA for quick testing and debugging.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><ol><li>Open a file containing APIs in your project</li><li>Click the gutter icon (▶) next to an API method to open it in the API Explorer</li><li>Configure request parameters (host, headers, body, etc.)</li><li>Click <strong>Send</strong> to execute the request</li></ol><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="pre-request-callback" tabindex="-1">Pre-request Callback <a class="header-anchor" href="#pre-request-callback" aria-label="Permalink to &quot;Pre-request Callback&quot;">​</a></h3><p>Use <code>http.call.before</code> to execute custom logic before sending a request:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">http.call.before</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:```</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logger.info(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Sending &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> + request.method() + </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot; &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> + request.url())</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span></code></pre></div><h3 id="post-request-callback" tabindex="-1">Post-request Callback <a class="header-anchor" href="#post-request-callback" aria-label="Permalink to &quot;Post-request Callback&quot;">​</a></h3><p>Use <code>http.call.after</code> to execute custom logic after receiving a response:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">http.call.after</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:```</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">if (response.code() == 200) {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    def </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">body</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = new JsonSlurper().parseText(response.body())</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    if (body.token) {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        localStorage.set(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, body.token)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span></code></pre></div><p>See <a href="/settings/rules/http_call_before">http.call.before</a> and <a href="/settings/rules/http_call_after">http.call.after</a> for more details.</p><h2 id="grpc-call" tabindex="-1">gRPC Call <a class="header-anchor" href="#grpc-call" aria-label="Permalink to &quot;gRPC Call&quot;">​</a></h2><p>EasyYapi also supports calling gRPC methods directly from the IDE. This feature is disabled by default; enable it in IDE settings:</p><p><kbd>Settings</kbd> &gt; <kbd>Other Settings</kbd> &gt; <kbd>EasyApi</kbd> &gt; <kbd>gRPC</kbd></p><p>Check the <strong>Enable gRPC call</strong> checkbox to enable gRPC call support.</p><p>When gRPC call is enabled, the plugin needs gRPC runtime JARs to invoke methods. You can configure the runtime dependencies via:</p><ul><li><strong>IDE Settings</strong>: Use the <strong>Auto Detect</strong> button in <kbd>Settings</kbd> &gt; <kbd>Other Settings</kbd> &gt; <kbd>EasyApi</kbd> &gt; gRPC Runtime to automatically detect and resolve dependencies.</li></ul><p>See <a href="/framework/grpc">gRPC Framework Support</a> for more details on gRPC configuration.</p><h2 id="gutter-icon-navigation" tabindex="-1">Gutter Icon Navigation <a class="header-anchor" href="#gutter-icon-navigation" aria-label="Permalink to &quot;Gutter Icon Navigation&quot;">​</a></h2><p>EasyYapi adds a gutter icon (▶) next to API methods in the editor. Clicking this icon opens the <strong>API Explorer</strong> and navigates directly to the corresponding endpoint.</p><h3 id="supported-annotations" tabindex="-1">Supported Annotations <a class="header-anchor" href="#supported-annotations" aria-label="Permalink to &quot;Supported Annotations&quot;">​</a></h3><p>The gutter icon appears on methods annotated with:</p><table tabindex="0"><thead><tr><th>Framework</th><th>Annotations</th></tr></thead><tbody><tr><td>Spring MVC</td><td><code>@RequestMapping</code>, <code>@GetMapping</code>, <code>@PostMapping</code>, <code>@PutMapping</code>, <code>@DeleteMapping</code>, <code>@PatchMapping</code></td></tr><tr><td>JAX-RS</td><td><code>@GET</code>, <code>@POST</code>, <code>@PUT</code>, <code>@DELETE</code>, <code>@PATCH</code>, <code>@Path</code></td></tr><tr><td>gRPC</td><td>RPC methods in classes extending <code>BindableService</code> or annotated with <code>@GrpcService</code></td></tr></tbody></table><h3 id="auto-re-scan" tabindex="-1">Auto Re-scan <a class="header-anchor" href="#auto-re-scan" aria-label="Permalink to &quot;Auto Re-scan&quot;">​</a></h3><p>If the endpoint is not found in the current index (e.g., after a branch switch or when the file is new), clicking the gutter icon automatically triggers a re-scan of the containing file before navigating to the explorer.</p><h2 id="api-explorer" tabindex="-1">API Explorer <a class="header-anchor" href="#api-explorer" aria-label="Permalink to &quot;API Explorer&quot;">​</a></h2><p>EasyYapi provides an <strong>API Explorer</strong> tool window for browsing, testing, and managing API endpoints. Open it from the bottom tool window bar in IDEA.</p><h3 id="browsing-endpoints" tabindex="-1">Browsing Endpoints <a class="header-anchor" href="#browsing-endpoints" aria-label="Permalink to &quot;Browsing Endpoints&quot;">​</a></h3><p>The explorer displays all detected API endpoints in a tree view organized by module and class:</p><ul><li><strong>Color-coded methods</strong>: HTTP methods are color-coded (GET=blue, POST=green, PUT=orange, DELETE=red, PATCH=cyan) and gRPC endpoints are shown in purple with streaming type indicators (<code>gRPC:U</code> for Unary, <code>gRPC:S</code> for Server Streaming, <code>gRPC:C</code> for Client Streaming, <code>gRPC:B</code> for Bidirectional)</li><li><strong>Search</strong>: Type in the search field to filter endpoints by address, name, path, folder, description, or class name (case-insensitive, with debounced input)</li><li><strong>Toolbar actions</strong>: Refresh, Export, Collapse All, Expand All</li></ul><h4 id="what-the-search-box-accepts" tabindex="-1">What the search box accepts <a class="header-anchor" href="#what-the-search-box-accepts" aria-label="Permalink to &quot;What the search box accepts&quot;">​</a></h4><p>The explorer&#39;s search bar and <strong>Search Everywhere</strong> share one matcher, so both accept the same query grammar:</p><ul><li>One query can combine the <strong>address and the name</strong> — <code>user 用户</code> matches <code>/api/user/get</code> whose name is <code>获取用户信息</code></li><li><strong>Fuzzy matching</strong>: <code>aus用户</code> matches <code>/api/user/get</code> as a subsequence</li><li>Tokens shorter than three characters must match literally, so a two-letter query does not return almost every endpoint</li><li>A pasted path is never fuzzed: it stays a precise statement, which keeps a shortened URL working</li><li>A <strong>method prefix</strong> (<code>GET /users</code>) filters by HTTP verb, and path templates match concrete values (<code>/api/users/42</code> finds <code>/api/users/{id}</code>)</li><li>Results are ordered by score, so a literal path hit comes before a fuzzy one</li></ul><h3 id="endpoint-details" tabindex="-1">Endpoint Details <a class="header-anchor" href="#endpoint-details" aria-label="Permalink to &quot;Endpoint Details&quot;">​</a></h3><p>Selecting an endpoint in the tree opens the details panel on the right, which includes:</p><ul><li><strong>Request line</strong>: HTTP method, host URL (with history), path, Send and Reset buttons</li><li><strong>Tabbed parameter editor</strong>: <ul><li><strong>Path</strong> — Path parameters (e.g., <code>/users/{id}</code>)</li><li><strong>Params</strong> — Query string and cookie parameters</li><li><strong>Headers</strong> — Request headers</li><li><strong>Form</strong> — Form data parameters (for <code>application/x-www-form-urlencoded</code> or <code>multipart/form-data</code>)</li><li><strong>Body</strong> — JSON request body (with syntax highlighting)</li></ul></li><li><strong>Response panel</strong>: Status code, response body (with Pretty/Raw JSON toggle and Copy button), and response headers</li></ul><h4 id="binary-responses" tabindex="-1">Binary responses <a class="header-anchor" href="#binary-responses" aria-label="Permalink to &quot;Binary responses&quot;">​</a></h4><p>File responses (<code>octet-stream</code>, images, PDF, ZIP, …) are no longer decoded as text. The explorer shows them as a metadata summary with a <strong>Save as</strong> action so the original bytes survive:</p><table tabindex="0"><thead><tr><th>Response kind</th><th>What you see</th></tr></thead><tbody><tr><td>Text (JSON, XML, HTML…)</td><td>Body tab with the Pretty/Raw toggle. Bodies larger than 500,000 characters are truncated for display.</td></tr><tr><td>Binary</td><td>Content type, size and a <strong>Save as</strong> button — the bytes are streamed to a temp file, never rendered as text.</td></tr></tbody></table><p>In scripts the same distinction is exposed on the response object:</p><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>response.bytes()</code></td><td>Raw response bytes; <code>null</code> for a text response</td></tr><tr><td><code>response.saveBody(path)</code></td><td>Write the body to <code>path</code>; returns <code>false</code> when there is nothing to save</td></tr><tr><td><code>pm.response.responseSize</code></td><td>Body size <strong>in bytes</strong> (it used to report characters)</td></tr></tbody></table><h3 id="sending-requests" tabindex="-1">Sending Requests <a class="header-anchor" href="#sending-requests" aria-label="Permalink to &quot;Sending Requests&quot;">​</a></h3><ol><li>Select an endpoint in the tree</li><li>Configure the host, parameters, headers, and body as needed</li><li>Click <strong>Send</strong> to execute the request</li><li>View the response in the panel below</li></ol><p>For gRPC endpoints, the explorer checks that gRPC call is enabled and runtime dependencies are available before sending. If not configured, it prompts you to open the settings.</p><h3 id="context-menu" tabindex="-1">Context Menu <a class="header-anchor" href="#context-menu" aria-label="Permalink to &quot;Context Menu&quot;">​</a></h3><p>Right-click on endpoints or folders in the tree to access:</p><table tabindex="0"><thead><tr><th>Action</th><th>Description</th></tr></thead><tbody><tr><td><strong>Export</strong></td><td>Export selected endpoints to Markdown, YApi, Postman, cURL, HttpClient, Hoppscotch, OpenAPI, or ApiPost</td></tr><tr><td><strong>Copy API URL</strong></td><td>Copy the address of each selected endpoint, one per line, as <code>METHOD /path</code></td></tr><tr><td><strong>Copy Path</strong></td><td>Copy the endpoint path to clipboard</td></tr><tr><td><strong>Copy as cURL</strong></td><td>Copy a cURL command for the endpoint to clipboard</td></tr><tr><td><strong>Navigate to Source</strong></td><td>Jump to the source code of the endpoint</td></tr><tr><td><strong>Reset to Default</strong></td><td>Reset any user modifications to the default values</td></tr></tbody></table><p>Double-click an endpoint to navigate directly to its source code.</p><p><strong>Copy API URL</strong> copies the <em>address</em>, not just the path — <code>GET /api/user/get</code> rather than <code>/api/user/get</code>. The HTTP method is included because a path alone cannot distinguish <code>GET /user/{id}</code> from <code>PUT /user/{id}</code>. It resolves through the same entry point every export action uses, so a copied address always matches what an export of the same selection would contain. No host is added: the host is a deployment concern that the environment selector resolves. It can be turned off in <strong>Features</strong> (<code>Copy API URL</code>).</p><h3 id="search-everywhere" tabindex="-1">Search Everywhere <a class="header-anchor" href="#search-everywhere" aria-label="Permalink to &quot;Search Everywhere&quot;">​</a></h3><p>Use IntelliJ&#39;s <strong>Search Everywhere</strong> (double-press <code>Shift</code>) to find endpoints across the project. They appear under their own <strong>APIs</strong> tab and also in <strong>All</strong>, and accept every form listed in <a href="#what-the-search-box-accepts">What the search box accepts</a> above. Clicking a result navigates to the source method.</p><p>The <strong>APIs</strong> tab can be turned off in <strong>Features</strong> (<code>Search Everywhere</code>). It keeps reading the retained API index — which an explorer <strong>Refresh</strong> refills — so it still works even while API Scanning is off.</p><h3 id="postman-environment-sync" tabindex="-1">Postman Environment Sync <a class="header-anchor" href="#postman-environment-sync" aria-label="Permalink to &quot;Postman Environment Sync&quot;">​</a></h3><p>Environments can be synchronized <strong>bidirectionally</strong> between EasyYapi and Postman, so a host or token defined once is available in both places.</p><p>Sync lives on the environment selector inside the explorer:</p><ul><li>Click the <strong>Sync ▼</strong> button in the inline environment panel, or right-click the environment dropdown and choose an action from the menu</li><li><strong>Push to Postman</strong> — push the current project environment and its variables to Postman</li><li><strong>Pull from Postman</strong> — pull a Postman environment into the project (the local environment list refreshes afterwards)</li></ul><p>Both actions require a <strong>Postman API token</strong> configured in settings; until then the sync actions stay disabled. When pulling an environment whose name already exists locally, you resolve the conflict:</p><table tabindex="0"><thead><tr><th>Strategy</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Replace</strong></td><td>Local variables are replaced by the Postman values</td></tr><tr><td><strong>Merge</strong></td><td>Postman values win for keys present in both; local-only keys are kept</td></tr><tr><td><strong>Skip</strong></td><td>Leave the local environment untouched</td></tr></tbody></table><h3 id="auto-save" tabindex="-1">Auto-save <a class="header-anchor" href="#auto-save" aria-label="Permalink to &quot;Auto-save&quot;">​</a></h3><p>User modifications to request parameters, headers, host, and body are automatically saved and restored when you revisit the same endpoint. <strong>Reset to Default</strong> discards them and re-reads the values from the source, so fields newly added to a DTO appear again.</p>',61)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
